function validate([edges1, edges2, k]) {
  // A list of n - 1 edges on nodes 0..n-1 is a tree exactly when no edge closes a cycle.
  const isTree = edges => {
    const n = edges.length + 1;
    if (n < 2 || n > 1000) return false;
    const parent = Array.from({ length: n }, (_, i) => i);
    const find = x => { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; };
    for (const edge of edges) {
      if (edge.length !== 2 || edge.some(v => v < 0 || v >= n)) return false;
      const a = find(edge[0]), b = find(edge[1]);
      if (a === b) return false;
      parent[a] = b;
    }
    return true;
  };
  if (!isTree(edges1)) return 'edges1 must form a tree on nodes 0 to n - 1, with 2 <= n <= 1000.';
  if (!isTree(edges2)) return 'edges2 must form a tree on nodes 0 to m - 1, with 2 <= m <= 1000.';
  if (k < 0 || k > 1000) return 'k is between 0 and 1000.';
  return null;
}

