function maxTargetNodes(edges1, edges2, k) {
  function buildGraph(edges) {
    const graph = Array.from({ length: edges.length + 1 }, () => []);
    for (const [a, b] of edges) {
      graph[a].push(b);
      graph[b].push(a);
    }
    return graph;
  }

  function countWithin(graph, start, limit) {
    if (limit < 0) {
      return 0;
    }
    const depth = new Array(graph.length).fill(-1);
    depth[start] = 0;
    const queue = [start];
    for (let head = 0; head < queue.length; head++) {
      const node = queue[head];
      if (depth[node] === limit) {
        continue;
      }
      for (const next of graph[node]) {
        if (depth[next] === -1) {
          depth[next] = depth[node] + 1;
          queue.push(next);
        }
      }
    }
    return queue.length;
  }

  const graph1 = buildGraph(edges1);
  const graph2 = buildGraph(edges2);
  let bestSecond = 0;
  for (let v = 0; v < graph2.length; v++) {
    bestSecond = Math.max(bestSecond, countWithin(graph2, v, k - 1));
  }

  const answer = [];
  for (let i = 0; i < graph1.length; i++) {
    answer.push(countWithin(graph1, i, k) + bestSecond);
  }
  return answer;
}

