function maxTargetNodes(edges1, edges2, k) {
  const n = edges1.length + 1, m = edges2.length + 1;
  const answer = new Array(n).fill(0);
  // Try every possible new edge u - v, merge both trees into one graph of n + m nodes, and count by walking from each i.
  for (let u = 0; u < n; u++) {
    for (let v = 0; v < m; v++) {
      const adj = Array.from({ length: n + m }, () => []);
      const link = (a, b) => { adj[a].push(b); adj[b].push(a); };
      for (const [a, b] of edges1) link(a, b);
      for (const [a, b] of edges2) link(n + a, n + b);
      link(u, n + v);
      for (let i = 0; i < n; i++) {
        // The merged graph is a tree, so a walk that never steps back reaches each node along its only path.
        let count = 0;
        const walk = (node, parent, length) => {
          if (length > k) return;
          count++;
          for (const next of adj[node]) if (next !== parent) walk(next, node, length + 1);
        };
        walk(i, -1, 0);
        answer[i] = Math.max(answer[i], count);
      }
    }
  }
  return answer;
}

