function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const large = size === 'large';
  const makeTree = n => {
    const shape = pick(4);
    const edges = [];
    for (let child = 1; child < n; child++) {
      let parent;
      if (shape === 0) parent = pick(child); // random tree
      else if (shape === 1) parent = child - 1; // a path
      else if (shape === 2) parent = pick(Math.min(child, 1 + pick(3))); // hangs off the first few nodes, like a star
      else parent = Math.max(0, child - 1 - pick(3)); // long and thin, with short branches
      edges.push([parent, child]);
    }
    // Relabel the nodes, shuffle the edges and flip some of them, so labels say nothing about the shape.
    const label = Array.from({ length: n }, (_, i) => i);
    for (let i = n - 1; i > 0; i--) { const j = pick(i + 1); [label[i], label[j]] = [label[j], label[i]]; }
    for (let i = edges.length - 1; i > 0; i--) { const j = pick(i + 1); [edges[i], edges[j]] = [edges[j], edges[i]]; }
    return edges.map(([a, b]) => (rand() < 0.5 ? [label[a], label[b]] : [label[b], label[a]]));
  };
  // Large trees stay near 500 nodes: one BFS per node is quadratic, and the interpreter has 2 seconds per case.
  const n = large ? 400 + pick(101) : 2 + pick(6);
  const m = large ? 400 + pick(101) : 2 + pick(6);
  const k = large ? [pick(6), 5 + pick(40), pick(1001)][pick(3)] : pick(6);
  return [makeTree(n), makeTree(m), k];
}
